private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int startIndex = i;
    while (i < bb.limit) {
        byte octet = bb.get(i++);
        if ((octet & 0x80) == 0) { // is one octet character
            sb.append((char)octet);
        } else if ((octet & 0xF0) == 0xE0) { // is multibyte character
            int bytesRead = 0;
            char ch = decodeOctet(bb, i, startIndex, bytesRead);
            if (ch >= 0) {
                sb.append(ch);
                i += bytesRead;
            } else {
                return -1; // invalid encoding
            }
        }
    }
    return i;
}

private static char decodeOctet(ByteBuffer bb, int i, int startIndex, int bytesRead) {
    int octets = 0;
    if ((bb.get(i) & 0xE0) == 0xE0) { // 2 byte character
        octets = 2;
    } else if ((bb.get(i) & 0xF0) == 0xF0) { // 3 byte character
        octets = 3;
    }
    if (i + octets > bb.limit) {
        return -1; // invalid character
    }
    bytesRead = octets;
    int ch = bb.get(i) & ((1 << (6 - octets)) - 1);
    for (int j = 1; j < octets; ++j) {
        if ((bb.get(i+j) & 0xC0) != 0x80) {
            return -1; // invalid character
        }
        ch = (ch << 6) | (bb.get(i+j) & 0x3F);
    }
    return (char)ch;
}
