    int retIndex = i;
    while (retIndex < bb.length() && bb.getByte(retIndex) >= 0 && bb.getByte(retIndex) < 128) {
        sb.append((char) bb.getByte(retIndex));
        retIndex++;
    }
    if (retIndex < bb.length() && bb.getByte(retIndex) < 0) {
        int codepoint = bb.getByte(retIndex);
        int length = 0;
        if ((codepoint & 0xE0) == 0xC0) {
            length = 1;
        } else if ((codepoint & 0xF0) == 0xE0) {
            length = 2;
        } else if ((codepoint & 0xF8) == 0xF0) {
            length = 3;
        } else if ((codepoint & 0xFC) == 0xF8) {
            length = 4;
        } else if ((codepoint & 0xFE) == 0xFC) {
            length = 5;
        } else {
            throw new IllegalArgumentException("Invalid UTF-8 byte sequence");
        }
        if (retIndex + length >= bb.length()) {
            throw new IllegalArgumentException("Invalid UTF-8 byte sequence");
        }
        codepoint = 0;
        for (int j = 0; j < length; j++) {
            codepoint <<= 6;
            codepoint |= bb.getByte(retIndex + 1 + j) & 0x3F;
