public static <V, E> void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    Set<Set<V>> atoms = new HashSet<>();
    Set<Set<V>> separators = new HashSet<>();
    Map<Set<V>, Integer> fullComponentCount = new HashMap<>();
    Set<V> generators = new HashSet<>();
    LinkedList<V> meo = new LinkedList<>();
    Set<E> fillEdges = new HashSet<>();

    // Generate the vertices for the graph
    for (String key : resultMap.keySet()) {
        V vertex = target.addVertex(resultMap.get(key));
        atoms.add(vertex);
        separators.add(vertex);
        generators.add(vertex);
        fullComponentCount.put(vertex, 1);
    }

    // Generate the edges for the graph
    for (String key : resultMap.keySet()) {
        for (String neighborKey : resultMap.keySet()) {
            if (!key.equals(neighborKey)) {
                V neighborVertex = resultMap.get(neighborKey);
                if (!atoms.contains(neighborVertex)) {
                    continue;
                }
                if (!separators.contains(neighborVertex)) {
                    continue;
                }
                V vertex = generatePredicateVertex(target, key, neighborKey, resultMap);
                V neighborVertex = resultMap.get(neighborKey);
                E edge = generateEdge(target, vertex, neighborVertex);
                if (edge != null) {
                    fillEdges.add(edge);
                }
            }
        }
    }

    // Set the properties of the graph
    target.setAtoms(atoms);
    target.setSeparators(separators);
    target.setFullComponentCount(fullComponentCount);
    target.setGenerators(generators);
    target.setEdgeFillEdges(fillEdges);
    target.setMeo(meo);
}

private static <V, E> E generateEdge(Graph<V, E> target, V vertex, V neighborVertex) {
    E edge = null;
    if (vertex != null && neighborVertex != null) {
        V sourceVertex = target.getVertex(vertex);
        V targetVertex = target.getVertex(neighborVertex);
        if (sourceVertex != null && targetVertex != null) {
            edge = generateEdge(sourceVertex, targetVertex);
        }
    }
    return edge;
