private static <V, E> V generatePredicateVertex(Graph<V, E> target, String key, String neighborKey, Map<String, V> resultMap) {
    V vertex = null;
    for (V atom : getAtoms(target)) {
        vertex = target.addVertex(atom);
        target.addEdge(vertex, getPredicateVertex(target, key, neighborKey, resultMap));
    }
    return vertex;
}

private static <V, E> V getPredicateVertex(Graph<V, E> target, String key, String neighborKey, Map<String, V> resultMap) {
    V vertex = null;
    for (V atom : getAtoms(target)) {
        V predicateVertex = target.getVertex(atom);
        if (predicateVertex != null && target.getEdges(predicateVertex).size() == 0) {
            vertex = predicateVertex;
            break;
        }
    }
    if (vertex == null) {
        vertex = target.addVertex();
    }
    return vertex;
}

private static <V, E> Set<V> getAtoms(Graph<V, E> target) {
    Set<V> atoms = new HashSet<>();
    for (E edge : target.getEdges()) {
        atoms.add(edge.getSource());
        atoms.add(edge.getTarget());
    }
    return atoms;
}
